"""Mock Exam #1, part A: D1 and D2 items outside the case studies. All items original.
Exam level: 40-60 word stems, two or three constraints per stem, near-miss distractors."""
from bank_d1 import T
L = "https://learn.microsoft.com/en-us/azure/foundry/"
D1, D2 = "D1 · Plan and manage", "D2 · GenAI and agents"

def single(id, skill, stem, options, runner, runnerWhy, think, eli5, learn):
    return dict(id=id, type="single", skill=skill, stem=stem, options=options, answer=0, runner=runner, runnerWhy=runnerWhy, think=think, eli5=eli5, learn=learn)

NOTE = " NOTE: Each correct selection is worth one point."
