GOAL = ("You have agents that must answer from current policy content stored in an Azure AI Search index, an Azure Blob Storage container, and a OneLake lakehouse. "
        "Content changes daily. **Goal:** use only generally available features, keep answers current, and connect the agents to the knowledge without storing keys.")
def S(i, sol, ans, prem, apply, rule):
    return dict(id="m1-s" + str(i), type="solution", skill=D2, scenario=GOAL, stem="**Proposed solution:** " + sol + " Does this meet the goal?", answer=ans,
                think=T(prem, [["Several sources, GA","Knowledge base","Extractive retrieval"],["Composed answer from the KB","Preview","Answer synthesis"],["User-uploaded files","Wrong tool","File search"]],
                        apply, rule, "Connect retrieval pipelines directly to workflows and agent tools."),
                eli5="The librarian may fetch pages from three shelves; writing the essay for you is still being tested.", learn=L+"agents/concepts/what-is-foundry-iq")
A += [
 S(1, "You create a knowledge base over the three sources that uses extractive retrieval, and you connect each agent to the knowledge base's MCP endpoint by using the project's managed identity.", True,
   "That multi-source retrieval must be preview. Knowledge bases with extractive retrieval over these sources are GA.",
   [["\"extractive retrieval\"","GA: met."],["\"project's managed identity\"","No keys: met."],["Sources read in place","Current content: met."]], "GA knowledge base: extractive retrieval; agents connect over MCP with managed identity."),
 S(2, "You create the same knowledge base, enable answer synthesis so the agents receive composed answers, and connect each agent by using the project's managed identity.", False,
   "That synthesis is part of GA. It's still preview.",
   [["\"enable answer synthesis\"","Preview: not met."],["\"managed identity\"","Keyless is met, but one failure is enough."]], "Answer synthesis and query planning are preview."),
 S(3, "You export all documents nightly to a file search vector store attached to each agent, and the agents read the store by using the project's managed identity.", False,
   "That file search serves organisational knowledge. It's for documents users provide, and nightly copies lag daily changes.",
   [["\"export all documents nightly\"","Copies lag: currency at risk."],["\"file search\"","Wrong tool for curated sources."]], "File search = user-provided files, not curated organisational content."),
]
